package com.company.platform.integration.domain;import java.time.Instant;import java.util.*;
public record Connector(UUID id,UUID tenantId,String name,String code,String provider,String version,String direction,String protocol,String status,String configuration,Instant createdAt,Instant updatedAt){public Connector{if(id==null||tenantId==null||name==null||name.isBlank()||code==null||code.isBlank()||provider==null||version==null||direction==null||protocol==null||status==null||configuration==null||createdAt==null||updatedAt==null)throw new IllegalArgumentException("invalid connector");}public static Connector register(UUID t,String n,String c,String p,String v,String d,String pr,String cfg){Instant now=Instant.now();return new Connector(UUID.randomUUID(),t,n,c,p,v,d,pr,"REGISTERED",cfg,now,now);}public Connector enable(){return new Connector(id,tenantId,name,code,provider,version,direction,protocol,"ACTIVE",configuration,createdAt,Instant.now());}public Connector disable(){return new Connector(id,tenantId,name,code,provider,version,direction,protocol,"SUSPENDED",configuration,createdAt,Instant.now());}}
